from pathlib import Path
import base64, gzip

FILES = {
    'rate_simulator.py': '',
    'static/js/rate_simulator.js': '[... ELLIPSIZATION ...]',
    'static/css/rate_simulator.css': '',
}

for rel, payload in FILES.items():
    path = Path(rel)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(gzip.decompress(base64.b64decode(payload)))

Path('.github/rate_sim_v2_patch.py').unlink(missing_ok=True)
Path('.github/workflows/rate_sim_v2_patch.yml').unlink(missing_ok=True)
